on: workflow_dispatch
concurrency:
  group: purchase-routing-production
  cancel-in-progress: false
jobs:
  # The separate verify_release job supplies the selection described above.
  stage:
    needs: verify_release
    runs-on: ubuntu-latest
    environment: production
    timeout-minutes: 20
    permissions:
      id-token: write
    env:
      DIGEST: ${{ needs.verify_release.outputs.digest }}
      CONFIG: ${{ needs.verify_release.outputs.routing_config }}
      REPOSITORY: ${{ vars.ROUTING_IMAGE_REPOSITORY }}
      STABLE: ${{ needs.verify_release.outputs.serving_revision }}
      APP: ${{ vars.CONTAINER_APP }}
      RG: ${{ vars.RESOURCE_GROUP }}
    steps:
      - name: Sign in with the production job identity
        uses: azure/login@a457da9ea143d694b1b9c7c869ebb04ebe844ef5 # v2.3.0
        with:
          client-id: ${{ vars.AZURE_CLIENT_ID }}
          tenant-id: ${{ vars.AZURE_TENANT_ID }}
          subscription-id: ${{ vars.AZURE_SUBSCRIPTION_ID }}

import csv

with open("one-day-cohort.csv", newline="", encoding="utf-8") as source:
    rows = list(csv.DictReader(source))

ids = [row["request"] for row in rows]
if not ids or any(not key.strip() for key in ids) or len(set(ids)) != len(ids):
    raise ValueError("Missing or duplicate request identifiers")

assigned, decided, missing = [], [], []
for row in rows:
    horizon = int(row["followup_minutes"])
    if horizon != 1440:
        raise ValueError("Reconcile incomplete or differently defined follow-up")
    assignment = row["correct_assignment_minutes"]
    decision = row["decision_minutes"]
    for value in (assignment, decision):
        if value != "" and not 0 <= int(value) <= horizon:
            raise ValueError("Event outside the declared time window")
    expected_open = "true" if decision == "" else "false"
    if row["open_at_one_day"] != expected_open:
        raise ValueError("Decision time and one-day state disagree")
    if assignment == "":
        missing.append(row["request"])
    else:
        assigned.append(int(assignment))
    if decision != "":
        decided.append(int(decision))

print("submitted, decided, open:", len(rows), len(decided), len(rows) - len(decided))
print("assigned, within two minutes:", len(assigned), sum(m <= 2 for m in assigned))
print("missing correct assignment:", ", ".join(missing))
for name, times in [("assignment", assigned), ("decision", decided)]:
    rank = (len(rows) + 1) // 2
    milestone = sorted(times)[rank - 1] if len(times) >= rank else "unreached"
    print(name, "one-half milestone (minutes):", milestone)
